#!/bin/bash
# Nsight Compute comparison of the fused dequantizing GEMM with the plain fp16 GEMM on the same prefill (0.8B Q4_K_M, 1024 tokens, trainer paused by gpu_window.sh): instructions issued, tensor-pipe
# utilisation and the stall mix of one launch of each.
#   tools/ncu_fused.sh [fused-kernel-regex] [plain-kernel-regex] [launch-skip]
KEY="$HOME/.ssh/id_ed25519"
HOST="user@homelab"
KF="${1:-gemmq_q4k_f16}"; KP="${2:-gemm_nt_f16}"; SKIP="${3:-6}"
M="gpu__time_duration.sum,launch__registers_per_thread,launch__occupancy_limit_registers,launch__occupancy_limit_shared_mem,sm__warps_active.avg.pct_of_peak_sustained_active,smsp__inst_executed.sum,sm__pipe_tensor_op_hmma_cycles_active.avg.pct_of_peak_sustained_active,smsp__issue_active.avg.pct_of_peak_sustained_active,l1tex__throughput.avg.pct_of_peak_sustained_elapsed,dram__throughput.avg.pct_of_peak_sustained_elapsed,"
M+="smsp__warp_issue_stalled_barrier_per_warp_active.pct,smsp__warp_issue_stalled_long_scoreboard_per_warp_active.pct,smsp__warp_issue_stalled_short_scoreboard_per_warp_active.pct,smsp__warp_issue_stalled_mio_throttle_per_warp_active.pct,smsp__warp_issue_stalled_math_pipe_throttle_per_warp_active.pct,smsp__warp_issue_stalled_wait_per_warp_active.pct,smsp__warp_issue_stalled_lg_throttle_per_warp_active.pct,smsp__warp_issue_stalled_not_selected_per_warp_active.pct,smsp__warp_issue_stalled_selected_per_warp_active.pct,smsp__warp_issue_stalled_dispatch_stall_per_warp_active.pct,smsp__warp_issue_stalled_no_instruction_per_warp_active.pct,smsp__warp_issue_stalled_tex_throttle_per_warp_active.pct"
exec ssh -i "$KEY" -o BatchMode=yes -o IdentitiesOnly=yes -o ConnectTimeout=10 "$HOST" "cd ~/forgeinfer/src; MODEL=\$HOME/forgeinfer/oracle/models/unsloth__Qwen3.5-0.8B-GGUF/Qwen3.5-0.8B-Q4_K_M.gguf; BIN=\$HOME/forgeinfer/target-dev/release/forge; for pair in 'fused:$KF:' 'plain:$KP:FORGE_NO_FUSED=1'; do name=\${pair%%:*}; rest=\${pair#*:}; k=\${rest%%:*}; envv=\${rest#*:}; echo \"=== \$name (\$k)\"; bash tools/gpu_window.sh env \$envv sudo -n --preserve-env=FORGE_NO_FUSED \$HOME/cuda-13.2.0/bin/ncu --clock-control none --kernel-name regex:\"^\$k\\$\" --launch-skip $SKIP --launch-count 1 --metrics $M \$BIN prefill-bench \$MODEL --native --tokens 1024 --reps 2 2>&1 | grep -E 'Duration|pct|\.sum|per_cycle|launch__|^  [a-z_0-9]+ \(' | grep -v '^run '; done"
